import {icon,escapeHtml as esc} from './components.js';
import {openPdfViewer} from './pdf-viewer.js';
const labels={setup_required:'API 설정 필요',login_required:'사용자 로그인 필요',subscription_required:'채널 구독 필요',connecting:'PDF 가져오는 중',connected:'',retrying:'재연결 중',disconnected:'수집기 연결 끊김'};
const fields={stockName:'종목',ticker:'티커',targetPrice:'목표주가',rating:'투자의견'};
function reportCard(r,canManage){
 const a=r.attachment,value=key=>key==='targetPrice'?(r.targetPriceInfo?.value||r.fields?.[key]?.value):r.fields?.[key]?.value;
 const title=value('title')||a.filename;
 const category=canManage?`<select class="report-category" data-category-id="${esc(r.id)}" aria-label="리포트 분류 변경">${[['auto','자동 분류'],['market','지수·시장'],['company','종목별'],['unclassified','미분류']].map(([key,label])=>`<option value="${key}" ${key===(r.classificationMode==='manual'?r.kind:'auto')?'selected':''}>${label}</option>`).join('')}</select>`:'';
 const date=value('issuedDate')||new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Seoul'}).format(new Date(r.postedAt));
 const revision=['up','down'].includes(r.targetPriceInfo?.revision)?r.targetPriceInfo.revision:null;
 const values=r.kind==='company'?Object.keys(fields).filter(key=>value(key)||key==='targetPrice'&&revision):[];
 const revisionLabel=revision?`<span class="report-target-${revision}" aria-label="목표주가 ${revision==='up'?'상향':'하향'}">${revision==='up'?'상향':'하향'}</span>`:'';
 const size=Number.isFinite(a.size)?(a.size/1024/1024>=1?(a.size/1024/1024).toFixed(1)+' MB':Math.ceil(a.size/1024)+' KB'):'';
 const fileStatus=a.status==='too_large'?'20MB를 초과한 파일입니다':a.status==='unavailable'?'파일을 가져오지 못했습니다':'PDF 준비 중';
 const stockUrl=r.kind==='company'&&['KR','US'].includes(r.market)&&r.ticker?'/stock/'+r.market+'/'+encodeURIComponent(r.ticker):null;
 const fieldValue=key=>stockUrl&&['stockName','ticker'].includes(key)?`<a class="report-stock-link" data-nav href="${esc(stockUrl)}" aria-label="${esc(value('stockName')||r.ticker)} 종목 상세 보기">${esc(value(key))}</a>`:esc(value(key)||'');
 return `<article class="report-card" data-report-card="${esc(r.id)}"><div class="report-card-top"><span class="report-file-type">${icon('report')} PDF${size?' · '+esc(size):''}</span><small class="report-reading-label">${r.reading?.unread===false?'읽음':'읽지 않음'}</small><time datetime="${esc(value('issuedDate')||r.postedAt)}" title="${value('issuedDate')?'발행일':'게시일'}">${esc(date)}</time></div><h3>${esc(title)}</h3><div class="report-byline">${esc(value('broker')||'')}${category}</div>${values.length?'<dl>'+values.map(key=>'<div><dt>'+fields[key]+'</dt><dd>'+fieldValue(key)+(key==='targetPrice'?revisionLabel:'')+'</dd></div>').join('')+'</dl>':''}${r.analyst?.evidence?.length?'<details class="report-issues"><summary>투자의견·목표주가 추출 근거</summary>'+r.analyst.evidence.map(e=>'<p>'+esc(e.text)+'</p>').join('')+'</details>':''}<div class="report-card-foot"><span class="report-filename" title="${esc(a.filename)}">${esc(a.filename)}</span>${a.status==='ready'?`<button class="report-open" data-reports="pdf" data-id="${esc(r.id)}">PDF 열기 ${icon('arrow')}</button>`:`<span class="report-file-status">${fileStatus}</span>`}</div></article>`;
}
export function mountReports(root,{stock=null}={}){
 let loadedKey=null;let requestedReport=new URLSearchParams(location.search).get('report');const state={kind:stock||requestedReport?'company':'market',offset:0,q:''};let controller,requestId=0,destroyed=false,viewer;const items=new Map();
 root.className=stock?'surface stock-reports':'reports-page';
 root.innerHTML='<div class="page-heading"><div><h'+(stock?'2':'1')+'>'+(stock?'종목 리포트':'리포트')+'</h'+(stock?'2':'1')+'></div><button class="icon-button" data-reports="refresh" aria-label="리포트 새로고침">'+icon('refresh')+'</button></div>'+(stock?'':'<div class="reports-tabs" role="group" aria-label="리포트 분류"><button data-reports="kind" data-kind="market" class="active" aria-pressed="true">지수·시장 리포트</button><button data-reports="kind" data-kind="company" aria-pressed="false">종목별 리포트</button><button data-reports="kind" data-kind="unclassified" aria-pressed="false">미분류</button></div><form class="reports-search"><input type="search" aria-label="리포트 종목명·제목 검색" placeholder="종목명 또는 제목 검색"><button type="submit">검색</button></form>')+'<div class="report-sources"></div><div class="report-list" aria-live="polite"></div><div class="reports-pages"><button data-reports="previous" hidden>이전</button><button data-reports="next" hidden>다음</button></div>';
 root.querySelectorAll('[data-reports="kind"]').forEach(b=>{const active=b.dataset.kind===state.kind;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 async function load(quiet=false){
  controller?.abort();controller=new AbortController();const id=++requestId,list=root.querySelector('.report-list'),loadKey=JSON.stringify([state.kind,state.offset,state.q,requestedReport]);const retain=loadKey===loadedKey&&items.size>0;list.setAttribute('aria-busy','true');if(!quiet&&!retain)list.innerHTML='<div class="data-state"><strong>리포트 불러오는 중</strong></div>';
  try{const params=new URLSearchParams({kind:state.kind,offset:String(state.offset),q:state.q});if(requestedReport)params.set('report',requestedReport);if(stock){params.set('market',stock.market);params.set('ticker',stock.id);}const response=await fetch('/api/reports?'+params,{signal:controller.signal});if(!response.ok)throw new Error();const data=await response.json();if(destroyed||id!==requestId)return;
   root.querySelector('.report-sources').innerHTML=(data.sources||[]).map(s=>{const valid=Number.isFinite(Date.parse(s.lastSyncAt));const date=valid?new Intl.DateTimeFormat('ko-KR',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Seoul',hour12:false}).format(new Date(s.lastSyncAt)):null;return '<span><b>'+esc(s.kind==='company'?'종목 리포트':s.kind==='market'?'시장 리포트':'리포트')+'</b> · '+esc(s.status==='connected'?'수집 연결됨':labels[s.status]||'연결 확인 필요')+' · '+(date?'마지막 동기화 '+esc(date)+' KST':'동기화 이력 없음')+'</span>';}).join('');
   loadedKey=loadKey;items.clear();for(const r of data.items||[])items.set(r.id,r);if(requestedReport&&data.items?.[0]?.attachment?.status==='ready'){viewer=openPdfViewer(data.items[0]);requestedReport=null;}
   root.querySelector('.report-refresh-error')?.remove();const setup=data.sources?.some(s=>['setup_required','login_required'].includes(s.status));
   list.innerHTML=data.items?.length?data.items.map(r=>reportCard(r,data.canManage)).join(''):'<div class="data-state"><div class="state-icon">'+icon('report')+'</div><strong>'+(data.status==='error'?'리포트를 불러오지 못했습니다':data.status==='restricted'?'공개 표시 설정 필요':setup?'텔레그램 사용자 계정 연결이 필요합니다':state.q?'검색 결과가 없습니다':'등록된 PDF 리포트가 없습니다')+'</strong></div>';
   root.querySelector('[data-reports="previous"]').hidden=state.offset===0;const next=root.querySelector('[data-reports="next"]');next.hidden=data.nextOffset===null||data.nextOffset===undefined;next.dataset.offset=data.nextOffset??'';
  }catch(error){if(error.name!=='AbortError'&&!destroyed&&id===requestId){const message='<div class="report-refresh-error" role="alert">연결 오류 · '+(retain?'마지막 조회 목록을 표시합니다. ':'')+'<button class="secondary-button" data-reports="refresh">다시 시도</button></div>';root.querySelector('.report-refresh-error')?.remove();if(retain)list.insertAdjacentHTML('beforebegin',message);else list.innerHTML=message;}}finally{if(id===requestId)list.removeAttribute('aria-busy');}
 }
 root.addEventListener('click',e=>{const b=e.target.closest('[data-reports]');if(!b)return;const action=b.dataset.reports;if(action==='pdf'){const report=items.get(b.dataset.id);if(report){viewer?.close();viewer=openPdfViewer(report);}return;}if(action==='kind'){state.kind=b.dataset.kind;state.offset=0;root.querySelectorAll('[data-reports="kind"]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});}if(action==='previous')state.offset=Math.max(0,state.offset-30);if(action==='next')state.offset=Number(b.dataset.offset);load();});
 root.addEventListener('change',async e=>{const select=e.target.closest('[data-category-id]');if(!select)return;const report=items.get(select.dataset.categoryId);if(!report)return;select.disabled=true;try{const response=await fetch('/api/reports/'+encodeURIComponent(report.id)+'/category',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:select.value})});if(!response.ok)throw new Error();state.offset=0;await load();}catch{select.value=report.classificationMode==='manual'?report.kind:'auto';const notice=document.createElement('span');notice.className='report-category-error';notice.setAttribute('role','alert');notice.textContent='분류 저장 실패';select.after(notice);}finally{select.disabled=false;}});
 root.querySelector('form')?.addEventListener('submit',e=>{e.preventDefault();state.q=root.querySelector('input').value.trim();state.offset=0;load();});
 load();const timer=setInterval(()=>{if(!document.hidden&&!root.closest('[hidden]')&&!viewer?.isOpen())load(true);},60000);
 const onRead=e=>{const r=[...items.values()].find(r=>r.attachment.url?.replace(/\/pdf$/,'/state')===e.detail?.url&&r.attachment.version===e.detail.version);if(r){r.reading={unread:false};const card=[...root.querySelectorAll('[data-report-card]')].find(el=>el.dataset.reportCard===r.id);if(card)card.querySelector('.report-reading-label').textContent='읽음';}};addEventListener('moa-document-read',onRead);
 return {destroy(){removeEventListener('moa-document-read',onRead);destroyed=true;controller?.abort();clearInterval(timer);viewer?.close();}};
}
